<?php

declare(strict_types=1);

use Pikaid\Pikaid;
use Pikaid\PikaidException;
use Pikaid\Tests\IndependentOracle;
use PHPUnit\Framework\TestCase;

/**
 * Pinned, same-value conformance matrix.
 *
 * The official fixture is the shared cross-SDK fixture. The additional matrix
 * was derived independently with Python big integers and is pinned by SHA-256;
 * it is never generated by src/Pikaid.php. Both files are checked against the
 * independent decimal-string oracle before the production entrypoints are used.
 */
final class PikaidConformanceTest extends TestCase
{
    private const OFFICIAL_FIXTURE_SHA256 = 'b0c9dfdd063613424414fef5c9065fbd2f81d645d0ab42b34e27cde715613500';
    private const OFFICIAL_SCHEMA_SHA256 = '4441d4dbaa6c5450ae9cbfb2438c53bc0421bba2b7fcc9ef9b158e5d1de0759e';
    private const MATRIX_SHA256 = '71e345d587a1b211531072e9bdc53dd6440e0d5f736ba442f6f982454994af44';
    private const SPEC_COMMIT = '17014d76f568c3ac9f9ce2927c1a018fdbc36d1d';

    /** @var array<string, mixed> */
    private static array $vectors;

    /** @var array<string, mixed> */
    private static array $matrix;

    public static function setUpBeforeClass(): void
    {
        $json = file_get_contents(__DIR__ . '/vectors/pikaid-v1.json');
        if ($json === false) {
            throw new RuntimeException('Cannot load conformance vectors.');
        }
        self::assertSame(self::OFFICIAL_FIXTURE_SHA256, hash('sha256', $json), 'official fixture digest');
        self::$vectors = json_decode($json, true, 512, JSON_THROW_ON_ERROR);

        $schema = file_get_contents(__DIR__ . '/vectors/pikaid-v1.schema.json');
        self::assertIsString($schema, 'official schema is readable');
        self::assertSame(self::OFFICIAL_SCHEMA_SHA256, hash('sha256', $schema), 'official schema digest');

        $matrix = file_get_contents(__DIR__ . '/vectors/conformance-matrix.json');
        if ($matrix === false) {
            throw new RuntimeException('Cannot load the conformance matrix.');
        }
        self::assertSame(self::MATRIX_SHA256, hash('sha256', $matrix), 'conformance matrix digest');
        self::$matrix = json_decode($matrix, true, 512, JSON_THROW_ON_ERROR);
    }

    public function testPinnedMetadata(): void
    {
        self::assertSame('1.0.4', self::$vectors['meta']['spec_revision']);
        self::assertSame('1.0.4', self::$matrix['meta']['spec_revision']);
        self::assertSame('v1.0.4', self::$matrix['meta']['spec_tag']);
        self::assertSame(self::SPEC_COMMIT, self::$matrix['meta']['spec_commit']);
        self::assertSame(self::OFFICIAL_FIXTURE_SHA256, self::$matrix['meta']['official_fixture_sha256']);
        self::assertSame(26, self::$matrix['meta']['string_length']);
        self::assertSame(17, self::$matrix['meta']['binary_length']);
        self::assertSame(78364164095, self::$matrix['meta']['timestamp_max']);
        self::assertSame(Pikaid::MAX_TIMESTAMP, self::$matrix['meta']['timestamp_max']);
        self::assertSame(96, self::$matrix['meta']['entropy_bits']);
    }

    public function testOfficialVectorsRoundTripAndParse(): void
    {
        foreach (self::$vectors['valid'] as $vector) {
            $this->assertCanonicalCase($vector, 'official/' . $vector['name']);
        }
    }

    public function testMatrixRoundTripsAcrossEveryPublicEntrypoint(): void
    {
        self::assertGreaterThanOrEqual(20, count(self::$matrix['valid']));

        foreach (self::$matrix['valid'] as $case) {
            $this->assertCanonicalCase($case, 'matrix/' . $case['name']);
        }
    }

    public function testIndependentOracleMatchesPinnedMatrix(): void
    {
        foreach (self::$matrix['valid'] as $case) {
            $entropy = hex2bin($case['entropy_hex']);
            self::assertIsString($entropy, $case['name']);

            self::assertSame($case['id'], IndependentOracle::encode($case['timestamp'], $entropy), $case['name'] . '/oracle-string');
            self::assertSame($case['bin_hex'], bin2hex(IndependentOracle::binary($case['timestamp'], $entropy)), $case['name'] . '/oracle-binary');
        }
    }

    public function testInvalidStringMatrixIsRejectedWithExactCodes(): void
    {
        foreach (self::$matrix['invalid']['string'] as $case) {
            $id = $case['id'];

            self::assertSame($case['shape_valid'], Pikaid::isWellFormed($id), $case['name'] . '/shape-only');
            self::assertFalse(Pikaid::isValid($id), $case['name'] . '/semantic validity');

            $this->assertPikaidCode($case['code'], static function () use ($id): void {
                Pikaid::validateOrThrow($id);
            }, $case['name'] . '/validateOrThrow');

            $this->assertPikaidCode($case['code'], static function () use ($id): void {
                Pikaid::toBinary($id);
            }, $case['name'] . '/toBinary');

            $this->assertPikaidCode($case['code'], static function () use ($id): void {
                Pikaid::parse($id);
            }, $case['name'] . '/parse');
        }
    }

    public function testInvalidBinaryMatrixIsRejectedWithExactCodes(): void
    {
        foreach (self::$matrix['invalid']['binary'] as $case) {
            $binary = hex2bin($case['bin_hex']);
            self::assertIsString($binary, $case['name'] . '/hex');

            $this->assertPikaidCode($case['code'], static function () use ($binary): void {
                Pikaid::fromBinary($binary);
            }, $case['name']);
        }
    }

    public function testStringEntrypointsRejectNonStringTypesUnderStrictTypes(): void
    {
        $valid = Pikaid::fromBinary(hex2bin('006553f10000112233445566778899aabb') ?: '');
        $values = [
            'null' => null,
            'int' => 123,
            'float' => 1.5,
            'bool' => true,
            'array' => [],
            'object' => new stdClass(),
        ];

        $operations = [
            'isValid' => static function ($value) use ($values): void { Pikaid::isValid($value); },
            'isWellFormed' => static function ($value): void { Pikaid::isWellFormed($value); },
            'validateOrThrow' => static function ($value): void { Pikaid::validateOrThrow($value); },
            'toBinary' => static function ($value): void { Pikaid::toBinary($value); },
            'fromBinary' => static function ($value): void { Pikaid::fromBinary($value); },
            'decode' => static function ($value): void { Pikaid::decode($value); },
            'getTimestamp' => static function ($value): void { Pikaid::getTimestamp($value); },
            'getEntropyBytes' => static function ($value): void { Pikaid::getEntropyBytes($value); },
            'getEntropyHex' => static function ($value): void { Pikaid::getEntropyHex($value); },
            'parse' => static function ($value): void { Pikaid::parse($value); },
            'compare-left' => static function ($value) use ($valid): void { Pikaid::compare($value, $valid); },
            'compare-right' => static function ($value) use ($valid): void { Pikaid::compare($valid, $value); },
        ];

        foreach ($values as $type => $value) {
            foreach ($operations as $name => $operation) {
                $this->assertTypeError(static function () use ($operation, $value): void {
                    $operation($value);
                }, $name . '/' . $type);
            }
        }

        // Timestamp APIs are int-typed, and fromDateTime is DateTimeInterface-typed.
        foreach (['string' => '1700000000', 'float' => 1.5, 'bool' => true, 'array' => [], 'null' => null] as $type => $value) {
            $this->assertTypeError(static function () use ($value): void {
                Pikaid::generateWithTimestamp($value);
            }, 'generateWithTimestamp/' . $type);
            $this->assertTypeError(static function () use ($value): void {
                Pikaid::generateBinaryWithTimestamp($value);
            }, 'generateBinaryWithTimestamp/' . $type);
            $this->assertTypeError(static function () use ($value): void {
                Pikaid::fromDateTime($value);
            }, 'fromDateTime/' . $type);
        }
    }

    public function testOrderingMatrixIsChronologicalForStringAndBinary(): void
    {
        $byName = [];
        foreach (self::$matrix['valid'] as $case) {
            $byName[$case['name']] = $case;
        }

        $ordered = [];
        foreach (self::$matrix['ordering'] as $name) {
            self::assertArrayHasKey($name, $byName);
            $ordered[] = $byName[$name];
        }

        for ($i = 0; $i < count($ordered) - 1; ++$i) {
            $a = $ordered[$i];
            $b = $ordered[$i + 1];

            self::assertLessThan(0, strcmp($a['id'], $b['id']), $a['name'] . ' < ' . $b['name'] . ' string');
            self::assertLessThan(0, strcmp(Pikaid::toBinary($a['id']), Pikaid::toBinary($b['id'])), $a['name'] . ' < ' . $b['name'] . ' binary');
            self::assertSame(-1, Pikaid::compare($a['id'], $b['id']));
            self::assertSame(1, Pikaid::compare($b['id'], $a['id']));
            self::assertSame(0, Pikaid::compare($a['id'], $a['id']));
        }
    }

    public function testSameSecondOrderFollowsRandomSuffixNotGenerationOrder(): void
    {
        $sameSecond = [];
        foreach (self::$matrix['valid'] as $case) {
            if ($case['timestamp'] === 1700000000) {
                $sameSecond[$case['name']] = $case;
            }
        }

        self::assertArrayHasKey('leading-zero-entropy', $sameSecond);
        self::assertArrayHasKey('sample-1700000000', $sameSecond);
        self::assertArrayHasKey('all-ff-entropy-at-sample', $sameSecond);

        self::assertSame(1700000000, Pikaid::getTimestamp($sameSecond['sample-1700000000']['id']));
        self::assertSame(1700000000, Pikaid::getTimestamp($sameSecond['all-ff-entropy-at-sample']['id']));
        self::assertLessThan(0, Pikaid::compare($sameSecond['leading-zero-entropy']['id'], $sameSecond['sample-1700000000']['id']));
        self::assertLessThan(0, Pikaid::compare($sameSecond['sample-1700000000']['id'], $sameSecond['all-ff-entropy-at-sample']['id']));
    }

    public function testShapeOnlyHelperDoesNotClaimSemanticValidity(): void
    {
        foreach (self::$matrix['invalid']['string'] as $case) {
            if ($case['shape_valid']) {
                self::assertTrue(Pikaid::isWellFormed($case['id']), $case['name']);
                self::assertFalse(Pikaid::isValid($case['id']), $case['name']);
            }
        }
    }

    /**
     * @param array{name: string, timestamp: int, entropy_hex: string, id: string, bin_hex: string} $case
     */
    private function assertCanonicalCase(array $case, string $label): void
    {
        $binary = hex2bin($case['bin_hex']);
        $entropy = hex2bin($case['entropy_hex']);
        self::assertIsString($binary, $label . '/binary-hex');
        self::assertIsString($entropy, $label . '/entropy-hex');
        self::assertSame(17, strlen($binary), $label . '/binary-length');
        self::assertSame(12, strlen($entropy), $label . '/entropy-length');
        self::assertSame(26, strlen($case['id']), $label . '/string-length');

        self::assertTrue(Pikaid::isWellFormed($case['id']), $label . '/well-formed');
        self::assertTrue(Pikaid::isValid($case['id']), $label . '/valid');
        self::assertSame($binary, Pikaid::toBinary($case['id']), $label . '/toBinary');
        self::assertSame($case['id'], Pikaid::fromBinary($binary), $label . '/fromBinary');
        self::assertSame($case['timestamp'], Pikaid::getTimestamp($case['id']), $label . '/timestamp');
        self::assertSame($case['entropy_hex'], Pikaid::getEntropyHex($case['id']), $label . '/entropy-hex');
        self::assertSame($entropy, Pikaid::getEntropyBytes($case['id']), $label . '/entropy-bytes');
        self::assertSame([$case['timestamp'], $entropy], Pikaid::decode($case['id']), $label . '/decode');
        self::assertSame(
            ['timestamp' => $case['timestamp'], 'entropy' => $entropy],
            Pikaid::validateOrThrow($case['id']),
            $label . '/validateOrThrow'
        );

        $parsed = Pikaid::parse($case['id']);
        self::assertSame(['timestamp', 'randomness', 'entropy_hex'], array_keys($parsed), $label . '/parse-keys');
        self::assertInstanceOf(DateTimeImmutable::class, $parsed['timestamp'], $label . '/immutable');
        self::assertSame('UTC', $parsed['timestamp']->getTimezone()->getName(), $label . '/utc');
        self::assertSame($case['timestamp'], $parsed['timestamp']->getTimestamp(), $label . '/parsed-timestamp');
        self::assertSame($case['entropy_hex'], $parsed['randomness'], $label . '/parsed-randomness');
        self::assertSame($parsed['randomness'], $parsed['entropy_hex'], $label . '/parse-alias');
    }

    private function assertPikaidCode(int $expected, callable $operation, string $label): void
    {
        try {
            $operation();
        } catch (PikaidException $exception) {
            self::assertInstanceOf(InvalidArgumentException::class, $exception, $label);
            self::assertSame($expected, $exception->getCode(), $label . ' code');
            return;
        }

        self::fail($label . ': expected PikaidException with code ' . $expected);
    }

    private function assertTypeError(callable $operation, string $label): void
    {
        try {
            $operation();
        } catch (TypeError $error) {
            self::assertNotSame('', $error->getMessage(), $label);
            return;
        }

        self::fail($label . ': expected TypeError under strict_types=1');
    }
}
